#include <bits/stdc++.h>
using namespace std;

class Solution {int m,n;vector<vector<vector<int>>> memo;vector<vector<char>> *g;bool dfs(int i,int j,int bal){if(i>=m||j>=n)return false;bal+=(*g)[i][j]=='('?1:-1;if(bal<0||bal>m+n)return false;if(i==m-1&&j==n-1)return bal==0;int &v=memo[i][j][bal];if(v!=-1)return v;return v=(dfs(i+1,j,bal)||dfs(i,j+1,bal));}public:bool hasValidPath(vector<vector<char>>& grid){m=grid.size();n=grid[0].size();if((m+n-1)%2||grid[0][0]==')'||grid[m-1][n-1]=='(')return false;g=&grid;memo.assign(m,vector<vector<int>>(n,vector<int>(m+n+1,-1)));return dfs(0,0,0);} };
